                    p.group_execute_bit(colours),
                    bit(p.other_read, "r", colours.other_read()),
                    bit(p.other_write, "w", colours.other_write()),
                    p.other_execute_bit(colours),
                ]
            }
            None => iter::repeat_n(colours.dash().paint("-"), 9).collect(),
        }
    }
